namespace sv_8ec5fc306f0945dab1b91f5d615dc811.Services;

/// <summary>
/// In-memory implementation of IChatService for development/demo purposes.
/// </summary>
public class InMemoryChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;

    public InMemoryChatService()
    {
        _channels = new List<Channel>
        {
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering topics and code reviews", 1),
            new(3, "design", "Design feedback and assets", 0),
            new(4, "random", "Off-topic banter and fun", 5),
            new(5, "announcements", "Important team announcements", 0),
        };

        var now = DateTime.UtcNow;
        _messages = new List<Message>
        {
            new(1, 1, "Alice", "Hey everyone! Welcome to the new chat app.", now.AddHours(-4), null, new() { new("👋", new() { "Bob", "Carol" }), new("🎉", new() { "Dave" }) }),
            new(2, 1, "Bob", "Looks great! Love the new UI.", now.AddHours(-3.5), null, new() { new("👍", new() { "Alice" }) }),
            new(3, 1, "Carol", "Thanks for setting this up.", now.AddHours(-3), null, new()),
            new(4, 1, "Dave", "Agreed, this is much better than email threads.", now.AddHours(-2), 1, new()),
            new(5, 1, "Alice", "Glad you all like it!", now.AddHours(-1.5), 1, new() { new("❤️", new() { "Bob", "Carol", "Dave" }) }),
            new(6, 1, "Eve", "Is there a mobile version?", now.AddMinutes(-45), null, new()),
            new(7, 1, "Bob", "Not yet, but it's on the roadmap.", now.AddMinutes(-30), 6, new()),
            new(8, 1, "Carol", "Can we add more channels?", now.AddMinutes(-10), null, new()),
            new(9, 2, "Alice", "PR #142 is ready for review.", now.AddHours(-2), null, new() { new("👀", new() { "Bob" }) }),
            new(10, 2, "Bob", "I'll take a look this afternoon.", now.AddHours(-1), 9, new()),
            new(11, 2, "Carol", "The CI pipeline is green.", now.AddMinutes(-20), null, new() { new("✅", new() { "Alice", "Bob" }) }),
            new(12, 4, "Dave", "Anyone up for trivia at lunch?", now.AddHours(-1), null, new() { new("🎯", new() { "Eve" }) }),
        };

        _nextMessageId = _messages.Max(m => m.Id) + 1;
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        return Task.FromResult(_channels.Select(c => c with { }).ToList());
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var messages = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderByDescending(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .OrderBy(m => m.SentAt)
            .ToList();

        return Task.FromResult(messages);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = _nextMessageId++;
        var message = new Message(id, channelId, "You", content, DateTime.UtcNow, replyToId, new List<Reaction>());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        var replies = _messages.Where(m => m.ReplyToId == rootMessageId).OrderBy(m => m.SentAt).ToList();

        var thread = new List<Message>();
        if (root != null) thread.Add(root);
        thread.AddRange(replies);
        return Task.FromResult(thread);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing != null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        return Task.CompletedTask;
    }
}

