.emoji-option:hover {
    background: #3a3b3e;
}

/* ── Message Input ── */

.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2c2d30;
    background: #1a1d21;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: 1px solid #3a3b3e;
    border-radius: 8px;
    padding: 10px 12px;
