    min-width: 260px;
    border-left: 1px solid #2c2d30;
    background: #1a1d21;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
}

.close-thread-btn {
    background: none;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #2c2d30;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #2c2d30;
    background: #222529;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #d1d2d3;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-reply {
    padding: 6px 8px;
}

/* ── Scrollbar styling ── */

.message-list::-webkit-scrollbar,
.thread-replies::-webkit-scrollbar,
.channel-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-thumb,
.thread-replies::-webkit-scrollbar-thumb,
.channel-list::-webkit-scrollbar-thumb {
    background: #3a3b3e;
    border-radius: 3px;
}

.message-list::-webkit-scrollbar-track,
.thread-replies::-webkit-scrollbar-track,
.channel-list::-webkit-scrollbar-track {
    background: transparent;
}

