@page "/chat"
@rendermode InteractiveServer
@using sv_8ec5fc306f0945dab1b91f5d615dc811.Services
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="chat-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel.Id)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <main class="chat-main @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h2># @_activeChannel.Name</h2>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="OnMessageListScroll" @ref="_messageListRef">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }

                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-card" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-header">
                                <span class="message-author">@msg.Author</span>
                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @* Reactions *@
                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ReactAsync(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @* Thread link *@
                            @{ var replyCount = GetReplyCount(msg.Id); }
                            @if (replyCount > 0)
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                    @replyCount @(replyCount == 1 ? "reply" : "replies")
                                </button>
                            }

                            @* Hover actions *@
                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg.Id)" title="Reply in thread">
                                        💬 Reply
                                    </button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)" title="Add reaction">
                                            😀 React
                                        </button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option" @onclick="() => ReactAsync(msg.Id, emoji)">
                                                        @emoji
                                                    </button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" placeholder="Type a message…" @bind="_newMessage"
                          @onkeydown="OnMessageKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessage)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* ── Right Panel: Thread View ── *@
    @if (_threadOpen && _threadMessages is not null)
    {
        <aside class="chat-thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            @if (_threadMessages.Count > 0)
            {
                <div class="thread-root-quote">
                    <span class="message-author">@_threadMessages[0].Author</span>
                    <p>@_threadMessages[0].Content</p>
                </div>

                <div class="thread-replies">
                    @foreach (var reply in _threadMessages.Skip(1))
                    {
                        <div class="message-card thread-reply">
                            <div class="message-header">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>

                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reactions-row">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ReactAsync(reply.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                </div>
            }

            <div class="message-input-area">
                <textarea class="message-textarea" placeholder="Reply in thread…" @bind="_threadReply"
                          @onkeydown="OnThreadKeyDown" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReply)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<Message>? _allChannelMessages; // includes replies, for counting
    private List<Message>? _threadMessages;

    private int _activeChannelId;
    private Channel? _activeChannel;
    private bool _threadOpen;
    private int _threadRootId;

    private string _newMessage = "";
    private string _threadReply = "";

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private bool _loadingMore;
    private int _messageSkip;
    private const int PageSize = 20;
    private bool _allMessagesLoaded;

    private ElementReference _messageListRef;

    private static readonly string[] _commonEmojis = { "👍", "❤️", "😂", "🎉", "👀", "🔥" };

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
            await SelectChannelAsync(_channels[0].Id);
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _allMessagesLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;

        // Load a broader set to count replies
        _allChannelMessages = _messages;

        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to clear unread badge
        _channels = await ChatService.GetChannelsAsync();

        CloseThread();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingMore || _allMessagesLoaded) return;
        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (older.Count == 0)
        {
            _allMessagesLoaded = true;
        }
        else
        {
            _messages = older.Concat(_messages!).ToList();
            _messageSkip += older.Count;
        }

        _loadingMore = false;
    }

    private async Task OnMessageListScroll()
    {
        // Scroll-to-top triggers loading older messages
        await LoadOlderMessagesAsync();
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessage)) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, _newMessage.Trim(), null);
        _messages?.Add(msg);
        _newMessage = "";
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
            await SendMessageAsync();
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
        _threadReply = "";
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadMessages = null;
        _threadReply = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReply)) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, _threadReply.Trim(), _threadRootId);
        _threadMessages?.Add(reply);
        _threadReply = "";
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
            await SendThreadReplyAsync();
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh the message list and thread to show updated reactions
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messageSkip > 0 ? _messageSkip : PageSize);
        if (_threadOpen)
            _threadMessages = await ChatService.GetThreadAsync(_threadRootId);
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private int GetReplyCount(int messageId)
    {
        // Count replies across _allChannelMessages or check thread
        return _allChannelMessages?.Count(m => m.ReplyToId == messageId) ?? 0;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 40 ? desc[..37] + "…" : desc;
    }
}

